def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            value = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        value += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(value)
                        break
                else:
                    value += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            value = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                value += line[i]
                i += 1
            fields.append(value)
            if i < n:
                i += 1  # Skip the comma

    return fields

